def control(obs):
    if obs['motion']['hold_s'] > 0:
        return (0.0, 0.0, 180)
    t = obs['t']
    h = obs['hitch_deg']
    st = obs['status']
    if STATE['phase'] == 'rev' and st in ('PINNED', 'JACKKNIFED'):
        STATE['phase'] = 'fwd'
        STATE['t0'] = None
    if STATE['phase'] == 'fwd':
        if STATE['t0'] is None:
            STATE['t0'] = t
        if t - STATE['t0'] < 3.0:
            return (0.0, 0.8, 180)
        STATE['phase'] = 'rev'
    steer = max(-34.0, min(34.0, 2.5 * (h - 2.0)))
    return (steer, -0.8, 180)

